    return {
      requests: {
        total: 0, // TODO: implement request counter
        active: 0
      },
      tasks: await this.services.taskManager.getMetrics(),
      connections: {
        sse: this.services.sseManager.getConnectionCount()
      }
    };
  }  async handleSSEConnection(requestId: string, request: FastifyRequest, reply: FastifyReply): Promise<void> {
    return await this.services.sseManager.handleSSERequest(requestId, request, reply);
